import type { MetadataRoute } from "next";
import { colors } from "@mct/ui/tokens";

export default function manifest(): MetadataRoute.Manifest {
  return {
    name: "Maine CyberTech Portal",
    short_name: "MCT Portal",
    description: "Managed IT services and cybersecurity platform",
    start_url: "/",
    display: "standalone",
    background_color: colors.cyber.base,
    theme_color: colors.cyber.accent,
    // MOB-P3-001: 192/512 PNGs are required for Chromium installability; the
    // maskable variant keeps the mark inside the Android safe zone. These are
    // generated by scripts/generate-pwa-icons.js (single source of truth).
    icons: [
      {
        src: "/icons/icon-192.png",
        sizes: "192x192",
        type: "image/png",
      },
      {
        src: "/icons/icon-512.png",
        sizes: "512x512",
        type: "image/png",
      },
      {
        src: "/icons/icon-512-maskable.png",
        sizes: "512x512",
        type: "image/png",
        purpose: "maskable",
      },
      {
        src: "/favicon.svg",
        sizes: "any",
        type: "image/svg+xml",
      },
    ],
  };
}
